-- BoardTrack full setup (generated by `npm run db:bundle`). Run on an EMPTY database:
--   psql -U <user> -d <your_db> -f db/boardtrack_full_setup.sql
BEGIN;
CREATE TABLE IF NOT EXISTS schema_migrations (name TEXT PRIMARY KEY, applied_at TIMESTAMPTZ DEFAULT now());
-- ===== migration 001_schema.sql =====
-- BoardTrack schema (PostgreSQL 13+; developed on 18). Fresh database expected.
CREATE EXTENSION IF NOT EXISTS btree_gist;  -- needed for the lease-overlap exclusion constraint
CREATE EXTENSION IF NOT EXISTS pgcrypto;    -- password hashing (crypt / gen_salt)

CREATE TABLE property (
  property_id   SERIAL PRIMARY KEY,
  property_name VARCHAR(100) NOT NULL,
  address       VARCHAR(255) NOT NULL
);

CREATE TABLE room (
  room_id      SERIAL PRIMARY KEY,
  property_id  INT NOT NULL REFERENCES property(property_id),
  room_number  VARCHAR(20) NOT NULL,
  monthly_rate NUMERIC(10,2) NOT NULL CHECK (monthly_rate > 0),
  status       VARCHAR(20) NOT NULL DEFAULT 'AVAILABLE'
               CHECK (status IN ('AVAILABLE','OCCUPIED','MAINTENANCE')),
  CONSTRAINT uq_room_per_property UNIQUE (property_id, room_number)
);

CREATE TABLE tenant (
  tenant_id       SERIAL PRIMARY KEY,
  full_name       VARCHAR(100) NOT NULL,
  contact_number  VARCHAR(20)  NOT NULL,
  email           VARCHAR(100) UNIQUE,
  valid_id_number VARCHAR(50)
);

CREATE TABLE lease (
  lease_id      SERIAL PRIMARY KEY,
  tenant_id     INT NOT NULL REFERENCES tenant(tenant_id),
  room_id       INT NOT NULL REFERENCES room(room_id),
  start_date    DATE NOT NULL,
  end_date      DATE NOT NULL,
  moved_out_on  DATE,
  monthly_rent  NUMERIC(10,2) NOT NULL CHECK (monthly_rent > 0),
  status        VARCHAR(20) NOT NULL DEFAULT 'ACTIVE'
                CHECK (status IN ('ACTIVE','TERMINATED','EXPIRED')),
  CONSTRAINT ck_lease_dates CHECK (end_date > start_date),
  CONSTRAINT ck_lease_moveout CHECK (moved_out_on IS NULL OR moved_out_on >= start_date),
  -- Business rule 2: no two ACTIVE leases on one room may overlap in time
  CONSTRAINT ex_lease_no_overlap EXCLUDE USING gist
    (room_id WITH =, daterange(start_date, end_date, '[]') WITH &&)
    WHERE (status = 'ACTIVE')
);

CREATE TABLE payment (
  payment_id     SERIAL PRIMARY KEY,
  lease_id       INT NOT NULL REFERENCES lease(lease_id),
  payment_date   DATE NOT NULL DEFAULT CURRENT_DATE,
  amount         NUMERIC(10,2) NOT NULL CHECK (amount > 0),
  payment_method VARCHAR(30) NOT NULL CHECK (payment_method IN ('CASH','GCASH','BANK_TRANSFER')),
  status         VARCHAR(20) NOT NULL DEFAULT 'COMPLETED'
                 CHECK (status IN ('COMPLETED','PENDING','FAILED'))
);

CREATE TABLE utility_bill (
  utility_bill_id SERIAL PRIMARY KEY,
  lease_id        INT NOT NULL REFERENCES lease(lease_id),
  billing_period  DATE NOT NULL CHECK (EXTRACT(DAY FROM billing_period) = 1), -- first day of month
  utility_type    VARCHAR(30) NOT NULL CHECK (utility_type IN ('ELECTRICITY','WATER','INTERNET')),
  amount          NUMERIC(10,2) NOT NULL CHECK (amount >= 0),
  status          VARCHAR(20) NOT NULL DEFAULT 'UNPAID' CHECK (status IN ('UNPAID','PAID'))
);

-- NEW in Activity 3: application login accounts and roles
CREATE TABLE app_user (
  user_id       SERIAL PRIMARY KEY,
  username      VARCHAR(50) NOT NULL UNIQUE,
  password_hash TEXT NOT NULL,
  role          VARCHAR(20) NOT NULL CHECK (role IN ('admin','staff','tenant')),
  tenant_id     INT REFERENCES tenant(tenant_id),
  is_active     BOOLEAN NOT NULL DEFAULT TRUE,
  CONSTRAINT ck_tenant_user CHECK ((role = 'tenant') = (tenant_id IS NOT NULL))
);

CREATE INDEX idx_lease_room    ON lease(room_id);
CREATE INDEX idx_lease_tenant  ON lease(tenant_id);
CREATE INDEX idx_payment_lease ON payment(lease_id);
CREATE INDEX idx_utility_lease ON utility_bill(lease_id);

-- Keep room.status in sync with lease state (MAINTENANCE is never overwritten).
-- Fires when a lease is added, its status/room changes, or it is deleted.
CREATE FUNCTION sync_room_status() RETURNS trigger AS $$
DECLARE target_room INT;
BEGIN
  IF TG_OP = 'DELETE' THEN target_room := OLD.room_id; ELSE target_room := NEW.room_id; END IF;
  UPDATE room r SET status = CASE WHEN EXISTS
      (SELECT 1 FROM lease l WHERE l.room_id = r.room_id AND l.status = 'ACTIVE')
      THEN 'OCCUPIED' ELSE 'AVAILABLE' END
  WHERE r.room_id = target_room AND r.status <> 'MAINTENANCE';
  IF TG_OP = 'UPDATE' AND OLD.room_id <> NEW.room_id THEN
    UPDATE room r SET status = CASE WHEN EXISTS
        (SELECT 1 FROM lease l WHERE l.room_id = r.room_id AND l.status = 'ACTIVE')
        THEN 'OCCUPIED' ELSE 'AVAILABLE' END
    WHERE r.room_id = OLD.room_id AND r.status <> 'MAINTENANCE';
  END IF;
  RETURN NULL;
END $$ LANGUAGE plpgsql;

CREATE TRIGGER trg_lease_sync_room
AFTER INSERT OR UPDATE OF status, room_id OR DELETE ON lease
FOR EACH ROW EXECUTE FUNCTION sync_room_status();

-- Stops people from hand-editing a room into a status that contradicts its leases.
CREATE FUNCTION guard_room_status() RETURNS trigger AS $$
DECLARE has_active BOOLEAN;
BEGIN
  SELECT EXISTS (SELECT 1 FROM lease WHERE room_id = NEW.room_id AND status = 'ACTIVE') INTO has_active;
  IF NEW.status = 'OCCUPIED' AND NOT has_active THEN
    RAISE EXCEPTION 'A room can only be OCCUPIED while it has an ACTIVE lease.';
  ELSIF NEW.status = 'AVAILABLE' AND has_active THEN
    RAISE EXCEPTION 'This room has an ACTIVE lease, so it cannot be AVAILABLE. Terminate the lease first.';
  END IF;
  RETURN NEW;
END $$ LANGUAGE plpgsql;

CREATE TRIGGER trg_room_status_guard
BEFORE INSERT OR UPDATE OF status ON room
FOR EACH ROW EXECUTE FUNCTION guard_room_status();

-- Balances are computed on demand, never stored (per the normalization review)
CREATE VIEW v_lease_summary AS
SELECT l.lease_id, l.tenant_id, t.full_name AS tenant, p.property_name, r.room_number,
       l.start_date, l.end_date, l.monthly_rent, l.status,
       COALESCE((SELECT SUM(x.amount) FROM payment x
                 WHERE x.lease_id = l.lease_id AND x.status = 'COMPLETED'), 0) AS total_paid,
       COALESCE((SELECT SUM(u.amount) FROM utility_bill u
                 WHERE u.lease_id = l.lease_id), 0) AS utilities_billed
FROM lease l
JOIN tenant t   ON t.tenant_id = l.tenant_id
JOIN room r     ON r.room_id = l.room_id
JOIN property p ON p.property_id = r.property_id;

INSERT INTO schema_migrations(name) VALUES ('001_schema.sql') ON CONFLICT DO NOTHING;
